// Autorização declarada pelo responsável, sem aprovação manual para estudar.
const DojoGuardian=(()=>{
 const version='2026-10-29.1',contact='personalandrecordeiro@gmail.com';
 const consent='Autorizo o uso do San Dojo pelo aluno sob minha responsabilidade e o tratamento dos dados necessários à conta, ao salvamento do progresso e ao acompanhamento pelo sensei, conforme a política de privacidade. Sei que posso retirar esta autorização e pedir exclusão. Esta autorização não inclui publicidade personalizada, divulgação de imagem ou gravação de voz.';
 const originalAccountPage=accountPage;
 const permitted=g=>['approved','authorized'].includes(g?.status)&&g?.consent_version===version;
 const date=value=>new Date(value).toLocaleDateString('pt-BR');
 function requestForm(){return `<form id="guardian-request" class="guardian-form"><h2>Autorização do responsável</h2><p>O responsável legal adulto entra com sua própria conta Google e acompanha o aluno. Cada conta acompanha um aluno nesta versão.</p><label>Seu nome, como responsável<input name="guardian_name" required minlength="3" maxlength="80" autocomplete="name"></label><label>Vínculo com o aluno<select name="relationship" required><option value="">Selecione</option><option value="mae">Mãe</option><option value="pai">Pai</option><option value="responsavel_legal">Responsável legal</option></select></label><label>Como chamar o aluno<input name="learner_alias" required minlength="2" maxlength="40" autocomplete="off" placeholder="Primeiro nome ou apelido"></label><p class="week-note">Usamos o e-mail da sua conta para contato. Não envie documentos, senhas, data de nascimento ou informações de saúde.</p><div class="guardian-consent"><h3>Leia antes de autorizar</h3><p>${consent}</p><a href="privacidade.html" target="_blank" rel="noopener">Ler a política de privacidade</a><label class="guardian-check"><input type="checkbox" name="confirm" required> Sou responsável legal adulto pelo aluno, li o texto acima e dou esta autorização específica.</label></div><p>Depois de confirmar, o acesso às atividades é liberado automaticamente. Esta declaração não é uma verificação de idade ou parentesco.</p><button class="primary" type="submit">Autorizar e começar →</button><p role="status" id="guardian-status"></p></form>`;}
 function actions(){const A=DojoAccounts,open=['pending','processing'].includes(A.erasure?.status);return `<div class="info-panel guardian-panel"><h2>Privacidade e responsável</h2><p><a href="privacidade.html">Consultar a política de privacidade</a> · <a href="mailto:${contact}?subject=Privacidade%20San%20Dojo">Falar com André</a></p>${A.isAdmin?'<p>O acesso é automático após a autorização do responsável. Só sua conta administra vídeos, imagens e o acompanhamento dos alunos.</p><button class="outline" data-privacy-queue>Ver autorizações e pedidos →</button><div id="privacy-queue"></div>':open?`<div class="learning-callout"><h3>Pedido de exclusão registrado</h3><p>Solicitado em ${date(A.erasure.requested_at)}. Situação: ${A.erasure.status==='processing'?'em atendimento pelo sensei':'aguardando atendimento'}. As atividades estão pausadas. O registro do pedido não significa que os dados já foram apagados; André conferirá a identidade e tratará a exclusão.</p><button class="outline" data-cancel-erasure>Cancelar meu pedido de exclusão</button><p class="week-note">Cancelar não recupera dados já excluídos. Uma nova autorização permite retomar as atividades.</p></div>`:`${A.guardian&&A.guardian.status!=='withdrawn'?'<button class="outline" data-privacy-confirm="withdraw">Retirar autorização e pausar atividades</button>':''}<button class="text-button danger" data-privacy-confirm="erasure">Solicitar exclusão da conta e dos dados</button><div id="privacy-confirm"></div>`}<p role="status" id="privacy-status"></p></div>`;}
 accountPage=function(){
  const A=DojoAccounts;
  if(!A.user)return originalAccountPage().replace('Entre com sua conta Google ou Apple. No primeiro acesso, seu cadastro de aluno é criado automaticamente.','Responsável: entre com sua própria conta Google. Confirme a autorização e comece a estudar, sem esperar a liberação do sensei.').replace('Crianças devem acessar com acompanhamento do responsável.','Criança: peça a um responsável para fazer a entrada e acompanhar suas atividades.');
  if(A.isAdmin)return originalAccountPage()+actions();
  const g=A.guardian,open=['pending','processing'].includes(A.erasure?.status);let body='';
  if(!A.error&&!open){
   if(!A.active)body='<p>O acesso foi pausado pelo sensei. Fale com André para retomar as atividades.</p>';
   else if(permitted(g))body=`<div class="info-panel"><h2>Autorização registrada · acesso liberado</h2><p>Aluno: ${esc(g.learner_alias)}. Responsável: ${esc(g.guardian_name)}.</p><p>Você já pode estudar. Módulos e faixas ilustrativas avançam pelas notas e pelo XP, sem aprovação manual.</p><button class="primary" data-view="home">Começar minha jornada →</button></div>`;
   else body=`<div class="info-panel"><h2>${g?.status==='withdrawn'?'Autorize novamente para retomar':'Antes da primeira atividade'}</h2>${requestForm()}</div>`;
  }
  return originalAccountPage()+body+actions();
 };
 async function queue(){
  const panel=document.getElementById('privacy-queue');if(!panel)return;panel.textContent='Carregando…';
  try{
   const data=await DojoAccounts.privacyQueue(),students=await DojoAccounts.students(),profiles=Object.fromEntries(students.map(s=>[s.id,s]));
   panel.innerHTML=`<h3>Autorizações dos responsáveis</h3><p>O acesso é automático após a declaração do responsável. Este cadastro não verifica idade ou parentesco. A conta pode ser pausada em Alunos cadastrados se houver necessidade.</p>${data.guardians.map(g=>`<article class="guardian-review"><h4>${esc(g.learner_alias)}</h4><p>${esc(g.guardian_name)} · ${esc(profiles[g.user_id]?.email||'Conta cadastrada')}</p><p>${{authorized:'Autorização declarada · acesso automático',approved:'Conferência anterior preservada',pending:'Autorização anterior pendente',rejected:'Solicitação anterior devolvida',withdrawn:'Autorização retirada'}[g.status]||'Consultar registro'} · ${date(g.requested_at)}</p></article>`).join('')||'<p>Nenhuma autorização registrada.</p>'}<h3>Pedidos de exclusão</h3><p>Confira a identidade antes de apagar dados. Marcar atendimento não exclui a conta; a exclusão definitiva é feita no Supabase.</p>${data.requests.map(r=>`<article class="guardian-review"><h4>${esc(profiles[r.user_id]?.display_name||'Conta do aluno')}</h4><p>${esc(profiles[r.user_id]?.email||'')} · ${date(r.requested_at)} · ${r.status==='processing'?'Em atendimento':'Aguardando atendimento'}</p><p>Identificador: <code>${esc(r.user_id)}</code></p>${r.status==='pending'?`<button class="outline" data-process-erasure="${esc(r.user_id)}">Marcar em atendimento</button>`:''}</article>`).join('')||'<p>Nenhum pedido de exclusão pendente.</p>'}`;
  }catch{panel.textContent='Não foi possível carregar os pedidos. Tente novamente.';}
 }
 function resetLocal(){try{if(DojoAccounts.user)localStorage.removeItem('san-dojo-user-'+DojoAccounts.user.id);}catch{}}
 document.addEventListener('submit',async event=>{
  const form=event.target;if(form.id!=='guardian-request')return;event.preventDefault();form.querySelectorAll('button').forEach(b=>b.disabled=true);const status=form.querySelector('[role="status"]');status.textContent='Registrando autorização…';
  try{const data=new FormData(form);await DojoAccounts.privacyRpc('dojo_request_guardian',{p_name:String(data.get('guardian_name')),p_relationship:String(data.get('relationship')),p_alias:String(data.get('learner_alias')),p_version:version,p_confirm:data.get('confirm')==='on'});location.hash='home';location.reload();}
  catch{status.textContent='Não foi possível registrar. Confira os campos e tente novamente.';form.querySelectorAll('button').forEach(b=>b.disabled=false);}
 });
 document.addEventListener('click',async event=>{
  const e=event.target.closest('button');if(!e)return;const status=document.getElementById('privacy-status');
  if(e.hasAttribute('data-privacy-queue')){await queue();return;}
  if(e.dataset.privacyConfirm){const kind=e.dataset.privacyConfirm;document.getElementById('privacy-confirm').innerHTML=`<div class="guardian-consent"><h3>${kind==='withdraw'?'Retirar autorização?':'Solicitar exclusão?'}</h3><p>${kind==='withdraw'?'As atividades serão pausadas. Os dados existentes permanecem guardados até um pedido de exclusão. Você pode autorizar novamente para retomar, sem aprovação manual.':'As atividades serão pausadas e o pedido ficará registrado para André. Este botão não apaga os dados imediatamente. A exclusão definitiva será tratada após conferência.'}</p><button class="outline danger" data-execute-privacy="${kind}">${kind==='withdraw'?'Confirmar retirada':'Confirmar pedido de exclusão'}</button><button class="text-button" data-dismiss-privacy>Voltar</button></div>`;return;}
  if(e.hasAttribute('data-dismiss-privacy')){document.getElementById('privacy-confirm').innerHTML='';return;}
  if(e.dataset.executePrivacy||e.hasAttribute('data-cancel-erasure')||e.dataset.processErasure){e.disabled=true;try{
   if(e.dataset.processErasure){await DojoAccounts.privacyRpc('dojo_process_erasure',{p_user:e.dataset.processErasure});await queue();return;}
   if(e.hasAttribute('data-cancel-erasure'))await DojoAccounts.privacyRpc('dojo_cancel_erasure');
   else{await DojoAccounts.flush();await DojoAccounts.privacyRpc(e.dataset.executePrivacy==='withdraw'?'dojo_withdraw_guardian':'dojo_request_erasure',e.dataset.executePrivacy==='withdraw'?{}:{p_confirm:true});resetLocal();}
   location.reload();
  }catch{if(status)status.textContent='Não foi possível concluir. Tente novamente ou fale com André.';e.disabled=false;}}
 });
 return {version,consent};
})();
